 44	    public Xkh73DTO createNotification(Long userId, Xzv64 category, Xkh73Type type, String message) {
 45	        try {
 46	            Xrd81 user = userRepository.findById(userId)
 47	                    .orElseThrow(() -> new Xkh73Exception(
 48	                            Xkh73ErrorCode.NOTIFICATION_USER_NOT_FOUND,
 49	                            "사용자 ID: " + userId + "를 찾을 수 없습니다."
 50	                    ));
 51	
 52	            Xkh73 notification = buildNotification(user, category, type, message);
 53	            Xkh73 savedNotification = notificationRepository.save(notification);
 54	            log.info("알림 생성 완료: 사용자={}, 카테고리={}, 타입={}", user.getEmail(), category, type);
 55	
 56	
 57	            sendRealTimeNotification(user.getEmail(), toDTO(savedNotification));
 58	
 59	            return toDTO(savedNotification);
 60	        } catch (Xkh73Exception e) {
 61	            throw e;
 62	        } catch (Exception e) {
 63	            log.error("알림 생성 중 오류 발생: 사용자ID={}, 카테고리={}, 타입={}, 오류={}",
 64	                    userId, category, type, e.getMessage(), e);
