 72	    public List<Xkh73DTO> createNotificationForAll(Xkh73RequestDTO requestDTO) {
 73	        try {
 74	            List<Xrd81> allUsers = userRepository.findAll();
 75	            if (allUsers.isEmpty()) {
 76	                log.warn("알림 대상 사용자가 없습니다.");
 77	                return List.of();
 78	            }
 79	
 80	            log.info("전체 사용자 알림 생성 시작: 카테고리={}, 타입={}, 대상 사용자 수={}",
 81	                    requestDTO.getCategory(), requestDTO.getType(), allUsers.size());
 82	
 83	            List<Xkh73> notifications = createNotificationsForUsers(
 84	                    allUsers, requestDTO.getCategory(), requestDTO.getType(), requestDTO.getMessage());
 85	
 86	            List<Xkh73> savedNotifications = notificationRepository.saveAll(notifications);
 87	            log.info("전체 사용자 알림 생성 완료: 카테고리={}, 타입={}, 생성된 알림 수={}",
 88	                    requestDTO.getCategory(), requestDTO.getType(), savedNotifications.size());
 89	
